// Preview assets (poster, filmstrip, waveform) keyed by media path. Generated by Rust, cached on disk.
import { create } from "zustand";
import { api } from "../lib/backend";
import type { MediaAssets, MediaItem } from "../project/types";

interface AssetState {
  assets: Record<string, MediaAssets | undefined>;
  pending: Record<string, boolean>;
  request: (media: MediaItem) => void;
  reset: () => void;
}

const queue: MediaItem[] = [];
let running = 0;
const CONCURRENCY = 2;

function pump() {
  while (running < CONCURRENCY && queue.length) {
    const media = queue.shift()!;
    running += 1;
    api
      .mediaAssets(media.path, media.kind, media.duration, media.hasAudio)
      .then((assets) => useAssets.setState((s) => ({ assets: { ...s.assets, [media.path]: assets } })))
      .catch(() => useAssets.setState((s) => ({ assets: { ...s.assets, [media.path]: emptyAssets } })))
      .finally(() => {
        running -= 1;
        pump();
      });
  }
}

const emptyAssets: MediaAssets = { thumb: null, strip: null, stripCount: 0, stripFrameW: 96, stripFrameH: 54, wave: null };

export const useAssets = create<AssetState>((set, get) => ({
  assets: {},
  pending: {},
  request: (media) => {
    const { assets, pending } = get();
    if (assets[media.path] || pending[media.path]) return;
    set({ pending: { ...pending, [media.path]: true } });
    queue.push(media);
    pump();
  },
  reset: () => set({ assets: {}, pending: {} }),
}));
